#!/usr/bin/env node

"use strict";

const fs = require("fs");
const parseArgs = require("minimist");
const Jibo = require("@jibo/jibo-server-client");
const syslog = require("modern-syslog");
const identity_file = "/var/jibo/identity.json";
const url = require('url');

let args = process.argv.slice(2);
let argv = parseArgs(args);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help            print this message");
    console.log("  --credentials FILE   path to credentials.json");
    console.log("  --file FILE          logfile to upload");
    console.log("  --debug              enable debugging statements");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

let debug = false;
if (argv.debug) {
    debug = true;
}

if (!argv.credentials) {
    console.log("ERROR: credentials file not specified!");
    usage();
    process.exit(1);
}

if (!argv.file) {
    console.log("ERROR: file not specified!");
    usage();
    process.exit(1);
}
syslog.init("jibo-binary-log-client", syslog.LOG_PID | syslog.LOG_ODELAY, syslog.LOG_LOCAL0);

//const logsize = fs.statSync(argv.file).size;

function get_identity() {
    try {
        let id = JSON.parse(fs.readFileSync(identity_file));
        return id;
    } catch (error) {
        syslog.error("Failed to read identity:", error);
        process.exit(1);
    }
}

if (!fs.existsSync(argv.credentials)) {
    syslog.warn("ERROR: No credentials!");
    process.exit(1);
}

Jibo.config.loadFromPath(argv.credentials);

//TODO: uncomment on the robot
let identity = get_identity();

// TODO: use real credentials maybe
//Jibo.config.loadFromPath(argv.credentials);
// For now use Alexander's keys
// I've hardcoded accessKeyId/secretAccessKey from my personal account on stg2.
// Instead you should get these keys from platform
//Jibo.config.update({
//  region: 'stg2-entrypoint',
//  accessKeyId: '1laWGpzebymaqMQlIvKd',
//  secretAccessKey: '4ykcCbnhahRBVzKv8snZ73jojHUWk3TQ13mgVgKm'
//});

// This should be replaced with real session identifier
var sessionId = 'sample_session_' + Date.now();

// Now we're creating logs client and uploading binary for the session
var logsClient = new Jibo.Log();
logsClient.putBinaryAsync({ trackingId: sessionId }, function (binaryErr, binary) {
  if (binaryErr) {
    return console.error(binaryErr);
  }

  const uploadUrl = url.parse(binary.uploadUrl);
  const options = {
    method: 'PUT',
    host: uploadUrl.host,
    path: uploadUrl.path,
    headers: {
      Accept: '*/*',
      'content-type': 'application/octet-stream',
      'Content-Length': fs.statSync(argv.file).size //Content-Length is required to upload to AWS S3 pre-signed URL
    }
  }
  var request = require('https').request(options, res=>uploadCb(res, binary, argv));
  request.on('error', e => console.error(`problem with request: ${e.message}`));
  const readStream = fs.createReadStream(argv.file);
  readStream.on('data', chunk=>request.write(chunk))
  readStream.on('end', ()=>request.end())
});

function uploadCb(res, binary, argv){
    res.setEncoding('utf8');
    res.on('data', (chunk) => {
      console.log(`BODY: ${chunk}`);
    });
    res.on('end', () => {
      if (res.statusCode == 200){
      	syslog.info('Uploaded binary', argv.file);
        console.log('Uploaded binary', binary);
        // Now we're pushing several log entries for the session, all keys within payload will be searchable
        logsClient.putEvents({
          trackingId: sessionId,
          deviceId: 'your-friendly-robot-id',
          events: [{
            created: Date.now(),
            message: 'ASR_BINARY',
            payload: {
              url: binary.url,
              key1: argv.file, //add filename to payload
              key2: identity.serial_number
            }
          }]
        }, function (eventsErr, eventsResult) {
          if (eventsErr) {
          	syslog.error('Error uploading binary', argv.file, eventsErr);
            return console.error(eventsErr);
          }
          console.log(eventsResult);
        });
      }else{
        console.log(`STATUS: ${res.statusCode}, HEADERS: ${JSON.stringify(res.headers)}`);
      }
    });
}
